import sys

def max_chocolates(n, a, b, p, q):
    if a > n:
        count_ab = 0
    else:
        count_ab = n // a

    if b > n:
        count_b = 0
    else:
        count_b = n // b

    if a * b > n:
        count_ab = 0
    else:
        count_ab -= n // (a * b)

    count_a_not_b = count_ab + (n // a - count_ab)
    count_b_not_a = count_ab + (n // b - count_ab)

    if p >= q:
        return (count_a_not_b * p) + (count_b_not_a * q)
    else:
        return (count_a_not_b * q) + (count_b_not_a * p)

